void main() {
  final examples =
      jsonDecode(File('test/generated/model_examples.json').readAsStringSync())
          as Map<String, Object?>;
  for (final entry in _decoders.entries) {
    test('${entry.key} decodes a minimal payload', () {
      final decoded = entry.value(_minimal[entry.key]!);
      expect((decoded as dynamic).toJson(), isA<Map<String, Object?>>());
    });
    for (final example
        in (examples[entry.key] as List<Object?>?) ?? const <Object?>[]) {
      test('${entry.key} decodes a specification example', () {
        final decoded = entry.value(example as Map<String, Object?>);
        expect((decoded as dynamic).toJson(), isA<Map<String, Object?>>());
      });
    }
  }
}
